'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const { verifyInstalled, safeRelative } = require('../scripts/pack-module-candidates');
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-module-integrity-'));
const directory = path.join(root, 'node_modules/test-module'); fs.mkdirSync(directory, { recursive: true });
const pkg = JSON.stringify({ name: 'test-module', version: '1.0.0' });
fs.writeFileSync(path.join(directory, 'package.json'), pkg); fs.writeFileSync(path.join(directory, 'ui.js'), 'real-ui');
const hash = text => crypto.createHash('sha256').update(text).digest('hex');
const manifest = { modules: { test: { installName: 'test-module', name: 'test-module', version: '1.0.0', files: { 'package.json': hash(pkg), 'ui.js': hash('real-ui') } } } };
verifyInstalled(manifest, root);
fs.writeFileSync(path.join(directory, 'ui.js'), 'old-ui');
assert.throws(() => verifyInstalled(manifest, root), /stale or altered/);
for (const unsafe of ['../secret', '/absolute', 'ui/../../secret', 'ui\\secret', 'ui/./secret']) assert.equal(safeRelative(unsafe), false);
assert.equal(safeRelative('ui/app.js'), true);
const { contentAddressedArtifact } = require('../scripts/install-module-candidates');
const tarball = path.join(root, 'same-version.tgz');
fs.writeFileSync(tarball, 'old candidate'); const old = contentAddressedArtifact(tarball);
fs.writeFileSync(tarball, 'new candidate'); const updated = contentAddressedArtifact(tarball);
assert.notEqual(old.file, updated.file, 'same-version changes must invalidate the npm artifact address');
assert.equal(fs.readFileSync(old.file, 'utf8'), 'old candidate');
assert.equal(fs.readFileSync(updated.file, 'utf8'), 'new candidate');
assert.equal(contentAddressedArtifact(tarball).file, updated.file, 'identical bytes keep a stable content address');
console.log('module artifact integrity test PASS');
